CREATE TYPE "Role" AS ENUM ('SUPER_ADMIN', 'ADMIN', 'CUSTOMER');
CREATE TYPE "OrderStatus" AS ENUM ('PENDING_PAYMENT', 'PAID', 'PREPARING', 'SHIPPED', 'DELIVERED', 'CANCELLED');
CREATE TYPE "PaymentMethod" AS ENUM ('PIX', 'CREDIT_CARD', 'BOLETO');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING', 'APPROVED', 'DECLINED', 'REFUNDED');
CREATE TYPE "StockMovementType" AS ENUM ('IN', 'OUT', 'ADJUSTMENT', 'RESERVATION', 'RELEASE');

CREATE TABLE "User" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "cpf" TEXT, "phone" TEXT, "role" "Role" NOT NULL DEFAULT 'CUSTOMER', "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Address" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "label" TEXT, "recipient" TEXT NOT NULL, "street" TEXT NOT NULL, "number" TEXT NOT NULL, "complement" TEXT, "neighborhood" TEXT NOT NULL, "city" TEXT NOT NULL, "state" VARCHAR(2) NOT NULL, "postalCode" TEXT NOT NULL, "isDefault" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Address_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Brand" ("id" UUID NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "Brand_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Product" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "description" TEXT NOT NULL, "sku" TEXT NOT NULL, "barcode" TEXT, "price" DECIMAL(10,2) NOT NULL, "salePrice" DECIMAL(10,2), "active" BOOLEAN NOT NULL DEFAULT true, "featured" BOOLEAN NOT NULL DEFAULT false, "isNew" BOOLEAN NOT NULL DEFAULT false, "onSale" BOOLEAN NOT NULL DEFAULT false, "categoryId" UUID NOT NULL, "brandId" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Product_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductImage" ("id" UUID NOT NULL, "productId" UUID NOT NULL, "url" TEXT NOT NULL, "alt" TEXT, "position" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "ProductImage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductVariant" ("id" UUID NOT NULL, "productId" UUID NOT NULL, "sku" TEXT NOT NULL, "color" TEXT NOT NULL, "size" TEXT NOT NULL, "stock" INTEGER NOT NULL DEFAULT 0, "lowStockAt" INTEGER NOT NULL DEFAULT 3, CONSTRAINT "ProductVariant_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StockMovement" ("id" UUID NOT NULL, "variantId" UUID NOT NULL, "type" "StockMovementType" NOT NULL, "quantity" INTEGER NOT NULL, "reason" TEXT NOT NULL, "reference" TEXT, "actorId" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StockMovement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Favorite" ("userId" UUID NOT NULL, "productId" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Favorite_pkey" PRIMARY KEY ("userId", "productId"));
CREATE TABLE "Cart" ("id" UUID NOT NULL, "userId" UUID, "sessionId" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Cart_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CartItem" ("id" UUID NOT NULL, "cartId" UUID NOT NULL, "variantId" UUID NOT NULL, "quantity" INTEGER NOT NULL, CONSTRAINT "CartItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Coupon" ("id" UUID NOT NULL, "code" TEXT NOT NULL, "percentage" DECIMAL(5,2), "amount" DECIMAL(10,2), "active" BOOLEAN NOT NULL DEFAULT true, "startsAt" TIMESTAMP(3), "expiresAt" TIMESTAMP(3), "usageLimit" INTEGER, "usedCount" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "Coupon_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Order" ("id" UUID NOT NULL, "number" TEXT NOT NULL, "userId" UUID NOT NULL, "addressId" UUID, "status" "OrderStatus" NOT NULL DEFAULT 'PENDING_PAYMENT', "paymentMethod" "PaymentMethod" NOT NULL, "subtotal" DECIMAL(10,2) NOT NULL, "discount" DECIMAL(10,2) NOT NULL DEFAULT 0, "shipping" DECIMAL(10,2) NOT NULL DEFAULT 0, "total" DECIMAL(10,2) NOT NULL, "couponId" UUID, "shippingSnapshot" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Order_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrderItem" ("id" UUID NOT NULL, "orderId" UUID NOT NULL, "productId" UUID NOT NULL, "variantId" UUID NOT NULL, "productName" TEXT NOT NULL, "sku" TEXT NOT NULL, "color" TEXT NOT NULL, "size" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "unitPrice" DECIMAL(10,2) NOT NULL, "discount" DECIMAL(10,2) NOT NULL DEFAULT 0, CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Payment" ("id" UUID NOT NULL, "orderId" UUID NOT NULL, "provider" TEXT, "externalId" TEXT, "method" "PaymentMethod" NOT NULL, "status" "PaymentStatus" NOT NULL DEFAULT 'PENDING', "amount" DECIMAL(10,2) NOT NULL, "safeDetails" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrderHistory" ("id" UUID NOT NULL, "orderId" UUID NOT NULL, "status" "OrderStatus" NOT NULL, "note" TEXT, "actorId" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OrderHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" UUID NOT NULL, "actorId" UUID, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entityId" TEXT, "metadata" JSONB, "ipAddress" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "User_cpf_key" ON "User"("cpf"); CREATE INDEX "User_name_idx" ON "User"("name");
CREATE INDEX "Address_userId_idx" ON "Address"("userId"); CREATE UNIQUE INDEX "Category_name_key" ON "Category"("name"); CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug"); CREATE UNIQUE INDEX "Brand_name_key" ON "Brand"("name");
CREATE UNIQUE INDEX "Product_slug_key" ON "Product"("slug"); CREATE UNIQUE INDEX "Product_sku_key" ON "Product"("sku"); CREATE UNIQUE INDEX "Product_barcode_key" ON "Product"("barcode"); CREATE INDEX "Product_categoryId_active_idx" ON "Product"("categoryId", "active"); CREATE INDEX "Product_brandId_idx" ON "Product"("brandId"); CREATE INDEX "Product_featured_isNew_onSale_idx" ON "Product"("featured", "isNew", "onSale"); CREATE INDEX "ProductImage_productId_position_idx" ON "ProductImage"("productId", "position"); CREATE UNIQUE INDEX "ProductVariant_sku_key" ON "ProductVariant"("sku"); CREATE UNIQUE INDEX "ProductVariant_productId_color_size_key" ON "ProductVariant"("productId", "color", "size"); CREATE INDEX "ProductVariant_stock_idx" ON "ProductVariant"("stock"); CREATE INDEX "StockMovement_variantId_createdAt_idx" ON "StockMovement"("variantId", "createdAt");
CREATE UNIQUE INDEX "Cart_userId_key" ON "Cart"("userId"); CREATE UNIQUE INDEX "Cart_sessionId_key" ON "Cart"("sessionId"); CREATE UNIQUE INDEX "CartItem_cartId_variantId_key" ON "CartItem"("cartId", "variantId"); CREATE UNIQUE INDEX "Coupon_code_key" ON "Coupon"("code"); CREATE UNIQUE INDEX "Order_number_key" ON "Order"("number"); CREATE INDEX "Order_userId_createdAt_idx" ON "Order"("userId", "createdAt"); CREATE INDEX "Order_status_createdAt_idx" ON "Order"("status", "createdAt"); CREATE INDEX "Payment_externalId_idx" ON "Payment"("externalId"); CREATE INDEX "OrderHistory_orderId_createdAt_idx" ON "OrderHistory"("orderId", "createdAt"); CREATE INDEX "AuditLog_actorId_createdAt_idx" ON "AuditLog"("actorId", "createdAt"); CREATE INDEX "AuditLog_entity_entityId_idx" ON "AuditLog"("entity", "entityId");

ALTER TABLE "Address" ADD CONSTRAINT "Address_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Product" ADD CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Product" ADD CONSTRAINT "Product_brandId_fkey" FOREIGN KEY ("brandId") REFERENCES "Brand"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProductImage" ADD CONSTRAINT "ProductImage_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ProductVariant" ADD CONSTRAINT "ProductVariant_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "StockMovement" ADD CONSTRAINT "StockMovement_variantId_fkey" FOREIGN KEY ("variantId") REFERENCES "ProductVariant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Favorite" ADD CONSTRAINT "Favorite_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Favorite" ADD CONSTRAINT "Favorite_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CartItem" ADD CONSTRAINT "CartItem_cartId_fkey" FOREIGN KEY ("cartId") REFERENCES "Cart"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CartItem" ADD CONSTRAINT "CartItem_variantId_fkey" FOREIGN KEY ("variantId") REFERENCES "ProductVariant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Order" ADD CONSTRAINT "Order_addressId_fkey" FOREIGN KEY ("addressId") REFERENCES "Address"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Order" ADD CONSTRAINT "Order_couponId_fkey" FOREIGN KEY ("couponId") REFERENCES "Coupon"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_variantId_fkey" FOREIGN KEY ("variantId") REFERENCES "ProductVariant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "OrderHistory" ADD CONSTRAINT "OrderHistory_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
